# Reference values from OrdinaryDiffEqStabilizedRK (Julia): number of saved
# points, function evaluations and final state of the adaptive, fixed step,
# backward and callback solves of a semilinear heat equation.

stab_heat_setup <- function() {
  N <- 8
  heat <- function(u, p, t) {
    l <- c(0, u[-N]); r <- c(u[-1], 0)
    p[1] * (l - 2 * u + r) * (N + 1)^2 - 0.5 * u^3 + 0.1 * sin(t)
  }
  u0 <- sin(pi * seq_len(N) / (N + 1))
  list(fwd = ODEProblem(heat, u0, c(0, 0.3), c(1)),
       back = ODEProblem(function(u, p, t) -heat(u, p, t), u0, c(0.3, 0), c(1)))
}

stab_alg <- function(nm) switch(nm,
  ROCK2_int1 = ROCK2(eigen_est_interval = 1), ROCK2_ms = ROCK2(min_stages = 5, max_stages = 20),
  RKL1_ms = RKL1(min_stages = 4, max_stages = 9), RKG2_ee = RKG2(eigen_est = 400), get(nm)())

