  for (r in ref) {
    alg <- stab_alg(r[[1]])
    sol <- switch(r[[2]],
      adaptive = solve(pr$fwd, alg, reltol = 1e-4, abstol = 1e-6),
      fixed = solve(pr$fwd, alg, dt = 0.01, adaptive = FALSE),
      backward = solve(pr$back, alg, reltol = 1e-4, abstol = 1e-6),
      callback = solve(pr$fwd, alg, reltol = 1e-4, abstol = 1e-6, callback = cb, tstops = 0.1))
    lab <- paste(r[[1]], r[[2]])
    expect_identical(length(sol$t), r[[3]], label = lab)
    expect_identical(sol$stats$nf, r[[4]], label = lab)
    expect_equal(sol$u[[length(sol$u)]], r[[5]], tolerance = 1e-12, label = lab)
  }
