test_that("stabilized methods take a spectral radius bound", {
  pr <- stab_heat_setup()
  s1 <- solve(pr$fwd, RKG2(eigen_est = 400), reltol = 1e-4, abstol = 1e-6)
  s2 <- solve(pr$fwd, RKG2(eigen_est = function(u, p, t) 400), reltol = 1e-4, abstol = 1e-6)
  expect_identical(s1$t, s2$t)
  # the power iteration finds the largest eigenvalue of the Jacobian
  n <- 20
  lap <- function(u, p, t) (c(0, u[-n]) - 2 * u + c(u[-1], 0)) * (n + 1)^2
  prob <- ODEProblem(lap, sin(pi * seq_len(n) / (n + 1)), c(0, 0.05))
  sol <- solve(prob, RKC(), reltol = 1e-6, abstol = 1e-8)
  exact <- exp(-pi^2 * 0.05) * sin(pi * seq_len(n) / (n + 1))
  expect_equal(sol$u[[length(sol$u)]], exact, tolerance = 1e-2)
  for (alg in list(ROCK2(), ROCK4(), ESERK5(), SERK2(), TSRKC2(), RKL1(), RKG1(), RKMC2())) {
    s <- solve(prob, alg, reltol = 1e-6, abstol = 1e-8)
    expect_equal(s$u[[length(s$u)]], sol$u[[length(sol$u)]], tolerance = 1e-3, label = alg$name)
  }
})

